Here is a complete command-line calculator in Python that supports +, -, *, and / with safe division:

```python
def add(a, b):
    return a + b

def subtract(a, b):
    return a - b

def multiply(a, b):
    return a * b

def divide(a, b):
    if b == 0:
        return 'Error: division by zero'
    return a / b

def main():
    print('Simple Calculator')
    print('Operations: + - * /')
    while True:
        line = input('Enter expression (e.g. 3 + 5) or q to quit: ').strip()
        if line.lower() == 'q':
            break
        parts = line.split()
        if len(parts) != 3:
            print('Use format: number operator number')
            continue
        try:
            a = float(parts[0])
            op = parts[1]
            b = float(parts[2])
        except ValueError:
            print('Invalid numbers')
            continue
        if op == '+':
            result = add(a, b)
        elif op == '-':
            result = subtract(a, b)
        elif op == '*':
            result = multiply(a, b)
        elif op == '/':
            result = divide(a, b)
        else:
            print('Unknown operator')
            continue
        print('Result:', result)

if __name__ == '__main__':
    main()
```

Notes: uses `float` so decimals work; input is split on whitespace so the user types `3 + 5`; division by zero is handled explicitly rather than raising an exception.

