A complete rock-paper-scissors game:

```python
import random

BEATS = {'rock': 'scissors', 'scissors': 'paper', 'paper': 'rock'}

def winner(player, computer):
    if player == computer:
        return 'tie'
    if BEATS[player] == computer:
        return 'player'
    return 'computer'

def play():
    player_score = 0
    computer_score = 0
    while True:
        player = input('rock, paper, scissors, or q: ').strip().lower()
        if player == 'q':
            break
        if player not in BEATS:
            print('Invalid choice')
            continue
        computer = random.choice(list(BEATS))
        result = winner(player, computer)
        print(f'You: {player} | Computer: {computer} -> {result}')
        if result == 'player':
            player_score += 1
        elif result == 'computer':
            computer_score += 1
    print(f'Final: you {player_score}, computer {computer_score}')

if __name__ == '__main__':
    play()
```

Notes: `BEATS` maps each choice to what it defeats — a clean way to encode game rules.

Multiple ways to reverse a string in Python:

```python
def reverse_slice(s):
    return s[::-1]

def reverse_loop(s):
    out = []
    for ch in s:
        out.insert(0, ch)
    return ''.join(out)

def reverse_join(s):
    return ''.join(reversed(s))

def reverse_recursive(s):
    if len(s) <= 1:
        return s
    return reverse_recursive(s[1:]) + s[0]

if __name__ == '__main__':
    text = 'hello'
    print(reverse_slice(text))
    print(reverse_loop(text))
    print(reverse_join(text))
    print(reverse_recursive(text))
```

Notes: slicing `[::-1]` is the idiomatic way; the recursive version is elegant but blows the stack on long strings.

Iterative, recursive, and memoized Fibonacci:

```python
from functools import lru_cache

def fib_iter(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

@lru_cache(maxsize=None)
def fib_memo(n):
    if n < 2:
        return n
    return fib_memo(n - 1) + fib_memo(n - 2)

def fib_recursive(n):
    if n < 2:
        return n
    return fib_recursive(n - 1) + fib_recursive(n - 2)

if __name__ == '__main__':
    print([fib_iter(i) for i in range(10)])
    print(fib_memo(50))
```

Notes: `fib_iter` runs in O(n) time and O(1) space; `fib_recursive` is exponential and only for teaching; `fib_memo` is fast but uses memory.

Iterative and recursive factorial, plus `math.factorial`:

```python
import math

def factorial_iter(n):
    if n < 0:
        raise ValueError('Negative input')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def factorial_recursive(n):
    if n < 0:
        raise ValueError('Negative input')
    if n < 2:
        return 1
    return n * factorial_recursive(n - 1)

if __name__ == '__main__':
    print(factorial_iter(5))
    print(factorial_recursive(5))
    print(math.factorial(5))
```

Notes: `math.factorial` is fastest and handles big integers.

A timing decorator and a logger decorator:

```python
import functools
import time

def timer(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)
        finally:
            elapsed = time.perf_counter() - start
            print(f'{func.__name__} took {elapsed:.4f}s')
    return wrapper

def logged(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f'calling {func.__name__}(args={args}, kwargs={kwargs})')
        return func(*args, **kwargs)
    return wrapper

@timer
@logged
def slow_sum(n):
    return sum(range(n))

if __name__ == '__main__':
    print(slow_sum(1_000_000))
```

Notes: `functools.wraps` preserves the original function's metadata; decorators apply bottom-up.

Generators for lazy sequences:

```python
def count_up(n):
    i = 1
    while i <= n:
        yield i
        i += 1

def read_lines(path):
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            yield line.rstrip('\\n')

def fibonacci(limit):
    a, b = 0, 1
    for _ in range(limit):
        yield a
        a, b = b, a + b

if __name__ == '__main__':
    print(list(count_up(5)))
    print(list(fibonacci(10)))
    total = sum(x * x for x in count_up(1000))
    print('sum of squares:', total)
```

Notes: generators produce values one at a time using `yield`; they hold only one value in memory regardless of length.

