Debounce delays a function until input stops arriving:

```javascript
function debounce(fn, delay = 300) {
  let timer = null;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

const onSearch = debounce(query => {
  console.log('searching for:', query);
}, 400);

// Simulated typing
onSearch('a');
onSearch('ap');
onSearch('app');
// Only 'app' is logged after 400ms of silence
```

Notes: debounce waits for quiet; throttle (below) fires at a steady rate.

Throttle limits how often a function runs:

```javascript
function throttle(fn, interval = 200) {
  let last = 0;
  let timer = null;
  return function (...args) {
    const now = Date.now();
    const remaining = interval - (now - last);
    if (remaining <= 0) {
      if (timer) { clearTimeout(timer); timer = null; }
      last = now;
      fn.apply(this, args);
    } else if (!timer) {
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

const onScroll = throttle(() => console.log('scrolling', Date.now()), 250);
window.addEventListener('scroll', onScroll);
```

Notes: throttle fires at most once per interval; debounce fires only after quiet. Use throttle for scroll/resize, debounce for search input.

Deep clone with cycle handling:

```javascript
function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return seen.get(value);

  if (value instanceof Date) return new Date(value.getTime());
  if (value instanceof RegExp) return new RegExp(value.source, value.flags);
  if (Array.isArray(value)) {
    const arr = [];
    seen.set(value, arr);
    for (const item of value) arr.push(deepClone(item, seen));
    return arr;
  }
  if (value instanceof Map) {
    const m = new Map();
    seen.set(value, m);
    for (const [k, v] of value) m.set(deepClone(k, seen), deepClone(v, seen));
    return m;
  }
  if (value instanceof Set) {
    const s = new Set();
    seen.set(value, s);
    for (const v of value) s.add(deepClone(v, seen));
    return s;
  }
  const out = {};
  seen.set(value, out);
  for (const key of Object.keys(value)) out[key] = deepClone(value[key], seen);
  return out;
}

const original = { a: 1, b: { c: [1, 2, 3] } };
original.self = original;
const copy = deepClone(original);
console.log(copy.b.c);
```

Notes: `structuredClone` is built into modern browsers — use it if you do not need custom behaviour. This version handles cycles, Dates, RegExps, Maps, and Sets.

Memoization caches function results by arguments:

```javascript
function memoize(fn, keyFn = (...args) => JSON.stringify(args)) {
  const cache = new Map();
  return function (...args) {
    const key = keyFn(...args);
    if (cache.has(key)) return cache.get(key);
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

const slowSquare = n => {
  console.log('computing', n);
  return n * n;
};

const fastSquare = memoize(slowSquare);
console.log(fastSquare(5)); // computes
console.log(fastSquare(5)); // cached
console.log(fastSquare(6)); // computes
```

Notes: useful for pure functions only. For single-argument functions, use the argument directly as key. For objects, pass a custom `keyFn`.

A minimal event emitter class:

```javascript
class EventEmitter {
  constructor() {
    this.listeners = new Map();
  }

  on(event, handler) {
    if (!this.listeners.has(event)) this.listeners.set(event, new Set());
    this.listeners.get(event).add(handler);
    return () => this.off(event, handler);
  }

  off(event, handler) {
    const set = this.listeners.get(event);
    if (set) set.delete(handler);
  }

  emit(event, ...args) {
    const set = this.listeners.get(event);
    if (!set) return;
    for (const handler of [...set]) {
      try {
        handler(...args);
      } catch (err) {
        console.error('listener error:', err);
      }
    }
  }

  once(event, handler) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      handler(...args);
    };
    this.on(event, wrapper);
  }
}

const bus = new EventEmitter();
const stop = bus.on('greet', name => console.log('hello', name));
bus.emit('greet', 'Alice');
stop();
```

Notes: returns an unsubscribe function; `once` removes the handler after the first call; handler errors are caught so one failure does not stop others.

Running tasks with a concurrency limit:

```javascript
async function promisePool(tasks, limit = 5) {
  const results = new Array(tasks.length);
  let nextIndex = 0;

  async function worker() {
    while (true) {
      const i = nextIndex++;
      if (i >= tasks.length) return;
      try {
        results[i] = { status: 'ok', value: await tasks[i]() };
      } catch (err) {
        results[i] = { status: 'error', error: err };
      }
    }
  }

  const workers = Array.from({ length: Math.min(limit, tasks.length) }, worker);
  await Promise.all(workers);
  return results;
}

const makeTask = n => () => new Promise(res => setTimeout(() => res(n * 2), 100));

promisePool([makeTask(1), makeTask(2), makeTask(3), makeTask(4), makeTask(5)], 2)
  .then(res => console.log(res));
```

Notes: keeps at most `limit` promises alive at once — useful when calling rate-limited APIs.

Retry an async function with exponential backoff:

```javascript
async function retry(fn, { retries = 5, baseDelay = 200, maxDelay = 5000 } = {}) {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (err) {
      attempt++;
      if (attempt > retries) throw err;
      const delay = Math.min(maxDelay, baseDelay * 2 ** (attempt - 1));
      const jitter = Math.random() * delay * 0.1;
      await new Promise(r => setTimeout(r, delay + jitter));
    }
  }
}

let count = 0;
const flaky = async () => {
  count++;
  if (count < 3) throw new Error('temporary failure');
  return 'success';
};

retry(flaky).then(console.log).catch(console.error);
```

Notes: exponential backoff with jitter reduces thundering-herd effects. Cap delay with `maxDelay`.

