#include <stdio.h>

long fib_iter(int n) {
    long a = 0, b = 1, temp;
    for (int i = 0; i < n; i++) {
        temp = a + b;
        a = b;
        b = temp;
    }
    return a;
}

long fib_rec(int n) {
    if (n < 2) return n;
    return fib_rec(n - 1) + fib_rec(n - 2);
}

int main(void) {
    for (int i = 0; i < 10; i++) {
        printf("%d: %ld %ld\\n", i, fib_iter(i), fib_rec(i));
