Singly linked list with insert and print:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node* new_node(int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) { perror("malloc"); exit(1); }
    n->value = value;
    n->next = NULL;
    return n;
}

void append(Node **head, int value) {
    Node *n = new_node(value);
    if (!*head) { *head = n; return; }
    Node *cur = *head;
    while (cur->next) cur = cur->next;
    cur->next = n;
}

void print_list(Node *head) {
    for (Node *cur = head; cur; cur = cur->next)
        printf("%d -> ", cur->value);
    printf("NULL\\n");
}

void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    append(&head, 1);
    append(&head, 2);
    append(&head, 3);
    print_list(head);
    free_list(head);
    return 0;
}
```

Notes: always `free` every allocation; `Node**` is used in `append` so the head can be modified.

