Iterative and recursive binary search:

```python
def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def binary_search_recursive(arr, target, lo=0, hi=None):
    if hi is None:
        hi = len(arr) - 1
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if arr[mid] == target:
        return mid
    if arr[mid] < target:
        return binary_search_recursive(arr, target, mid + 1, hi)
    return binary_search_recursive(arr, target, lo, mid - 1)

if __name__ == '__main__':
    data = [1, 3, 5, 7, 9, 11, 13]
    print(binary_search(data, 7))
    print(binary_search_recursive(data, 7))
    print(binary_search(data, 4))
```

Notes: works only on sorted data. Complexity is O(log n) time, O(1) space for iterative.

Levenshtein distance with dynamic programming:

```python
def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(
                    dp[i-1][j],      # deletion
                    dp[i][j-1],      # insertion
                    dp[i-1][j-1],    # substitution
                )
    return dp[m][n]

if __name__ == '__main__':
    print(edit_distance('kitten', 'sitting'))  # 3
    print(edit_distance('python', 'pyton'))    # 1
```

Notes: complexity is O(m × n) time and space. Used in spell checkers, DNA comparison, and fuzzy matching.

