```python
from collections import deque

def bfs(graph, start):
    visited = {start}
    order = []
    queue = deque([start])
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return order

def shortest_path(graph, start, goal):
    if start == goal:
        return [start]
    visited = {start}
    queue = deque([(start, [start])])
    while queue:
        node, path = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor == goal:
                return path + [neighbor]
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

if __name__ == '__main__':
    g = {'A': ['B', 'C'], 'B': ['D'], 'C': ['E'], 'D': [], 'E': ['F'], 'F': []}
    print(bfs(g, 'A'))
    print(shortest_path(g, 'A', 'F'))
```

Notes: BFS finds the shortest path in unweighted graphs. Complexity is O(V + E).

DFS iteratively and recursively:

```python
def dfs_recursive(graph, node, visited=None):
    if visited is None:
        visited = set()
    if node in visited:
        return []
    visited.add(node)
    order = [node]
    for neighbor in graph.get(node, []):
        order.extend(dfs_recursive(graph, neighbor, visited))
    return order

def dfs_iterative(graph, start):
    visited = set()
    order = []
    stack = [start]
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        order.append(node)
        for neighbor in reversed(graph.get(node, [])):
            if neighbor not in visited:
                stack.append(neighbor)
    return order

if __name__ == '__main__':
    g = {'A': ['B', 'C'], 'B': ['D', 'E'], 'C': ['F'], 'D': [], 'E': [], 'F': []}
    print(dfs_recursive(g, 'A'))
    print(dfs_iterative(g, 'A'))
```

Notes: recursion uses the call stack; iteration uses an explicit stack. Complexity is O(V + E).

0/1 knapsack with dynamic programming:

```python
def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        w, v = weights[i-1], values[i-1]
        for cap in range(capacity + 1):
            dp[i][cap] = dp[i-1][cap]
            if w <= cap:
                dp[i][cap] = max(dp[i][cap], dp[i-1][cap - w] + v)
    return dp[n][capacity]

def knapsack_items(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        w, v = weights[i-1], values[i-1]
        for cap in range(capacity + 1):
            dp[i][cap] = dp[i-1][cap]
            if w <= cap:
                dp[i][cap] = max(dp[i][cap], dp[i-1][cap - w] + v)

    chosen = []
    cap = capacity
    for i in range(n, 0, -1):
        if dp[i][cap] != dp[i-1][cap]:
            chosen.append(i - 1)
            cap -= weights[i-1]
    return dp[n][capacity], list(reversed(chosen))

if __name__ == '__main__':
    weights = [2, 3, 4, 5]
    values = [3, 4, 5, 6]
    print(knapsack(weights, values, 5))
    print(knapsack_items(weights, values, 5))
```

Notes: O(n × capacity) time and space. The item reconstruction walks backward through the table to find which items were chosen.

A stack implemented with a list:

```python
class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError('peek from empty stack')
        return self._items[-1]

    def is_empty(self):
        return len(self._items) == 0

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return f'Stack({self._items})'

if __name__ == '__main__':
    s = Stack()
    s.push(1)
    s.push(2)
    s.push(3)
    print(s)
    print(s.pop())
    print(s.peek())
    print(len(s))
```

Notes: LIFO order; `pop` and `peek` raise on empty rather than returning `None`.

A queue using `collections.deque` for O(1) operations:

```python
from collections import deque

class Queue:
    def __init__(self):
        self._items = deque()

    def enqueue(self, item):
        self._items.append(item)

    def dequeue(self):
        if self.is_empty():
            raise IndexError('dequeue from empty queue')
        return self._items.popleft()

    def front(self):
        if self.is_empty():
            raise IndexError('front of empty queue')
        return self._items[0]

    def is_empty(self):
        return len(self._items) == 0

    def __len__(self):
        return len(self._items)

if __name__ == '__main__':
    q = Queue()
    q.enqueue('a')
    q.enqueue('b')
    q.enqueue('c')
    print(q.dequeue())
    print(q.front())
    print(len(q))
```

Notes: `deque.popleft()` is O(1); using `list.pop(0)` would be O(n).

A trie (prefix tree) for fast string lookup:

```python
class Trie:
    def __init__(self):
        self.root = {}
        self.end = '__end__'

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node[self.end] = True

    def search(self, word):
        node = self.root
        for ch in word:
            if ch not in node:
                return False
            node = node[ch]
        return self.end in node

    def starts_with(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node:
                return False
            node = node[ch]
        return True

    def autocomplete(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node:
                return []
            node = node[ch]
        results = []
        def walk(n, path):
            if self.end in n:
                results.append(prefix + path)
            for ch, child in n.items():
                if ch != self.end:
                    walk(child, path + ch)
        walk(node, '')
        return results

if __name__ == '__main__':
    t = Trie()
    for w in ['cat', 'car', 'card', 'care', 'dog']:
        t.insert(w)
    print(t.search('card'))
    print(t.starts_with('ca'))
    print(t.autocomplete('car'))
```

Notes: O(k) per operation where k is the word length. `autocomplete` walks the subtree under a prefix.

