Three ways to implement singleton in Python:

```python
# Method 1: __new__ override
class Singleton1:
    _instance = None
    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

# Method 2: module-level instance (simplest and most Pythonic)
class _Config:
    def __init__(self):
        self.settings = {}

config = _Config()  # import this

# Method 3: metaclass
class SingletonMeta(type):
    _instances = {}
    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class Singleton3(metaclass=SingletonMeta):
    pass

if __name__ == '__main__':
    a = Singleton1()
    b = Singleton1()
    print(a is b)  # True
    print(Singleton3() is Singleton3())  # True
```

Notes: prefer a module-level instance over a class-based singleton in Python — simpler and more explicit.

Factory pattern with a registry:

```python
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self): ...

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius
    def area(self):
        return 3.14159 * self.radius ** 2

class Rectangle(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h
    def area(self):
        return self.w * self.h

class ShapeFactory:
    _registry = {}

    @classmethod
    def register(cls, name, shape_cls):
        cls._registry[name] = shape_cls

    @classmethod
    def create(cls, name, *args, **kwargs):
        if name not in cls._registry:
            raise ValueError(f'Unknown shape: {name}')
        return cls._registry[name](*args, **kwargs)

ShapeFactory.register('circle', Circle)
ShapeFactory.register('rectangle', Rectangle)

if __name__ == '__main__':
    for name, args in [('circle', (5,)), ('rectangle', (4, 6))]:
        shape = ShapeFactory.create(name, *args)
        print(name, shape.area())
```

Notes: the registry makes the factory extensible — new shapes register themselves without changing the factory.

Observer pattern for event notification:

```python
class Observable:
    def __init__(self):
        self._observers = []

    def subscribe(self, observer):
        self._observers.append(observer)
        return lambda: self._observers.remove(observer)

    def notify(self, event):
        for observer in list(self._observers):
            observer(event)

class Store(Observable):
    def __init__(self):
        super().__init__()
        self.items = []

    def add(self, item):
        self.items.append(item)
        self.notify({'type': 'added', 'item': item, 'count': len(self.items)})

if __name__ == '__main__':
    store = Store()
    unsubscribe = store.subscribe(lambda e: print('Logger:', e))
    store.subscribe(lambda e: print('UI updated, total:', e['count']))

    store.add('apple')
    store.add('banana')

    unsubscribe()
    store.add('cherry')
```

Notes: `subscribe` returns an unsubscribe function — a clean way to detach. Always iterate over a copy of the list so unsubscribes during notification are safe.

