Finding duplicates in a list with several methods:

```python
from collections import Counter

def duplicates_counter(values):
    counts = Counter(values)
    return [item for item, count in counts.items() if count > 1]

def duplicates_set(values):
    seen = set()
    dupes = set()
    for v in values:
        if v in seen:
            dupes.add(v)
        seen.add(v)
    return list(dupes)

def first_duplicate(values):
    seen = set()
    for v in values:
        if v in seen:
            return v
        seen.add(v)
    return None

if __name__ == '__main__':
    data = [1, 2, 3, 2, 4, 5, 3, 6, 3]
    print(duplicates_counter(data))
    print(duplicates_set(data))
    print(first_duplicate(data))
```

Notes: `Counter` gives you the full count in one pass; `duplicates_set` is O(n) but loses order; `first_duplicate` returns as soon as a duplicate is found.

Flattening nested lists with several approaches:

```python
def flatten_recursive(values):
    result = []
    for v in values:
        if isinstance(v, list):
            result.extend(flatten_recursive(v))
        else:
            result.append(v)
    return result

def flatten_iterative(values):
    stack = list(values)
    result = []
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            stack.extend(reversed(item))
        else:
            result.append(item)
    return result

def flatten_any_depth(values, max_depth=None):
    def _walk(node, depth):
        for v in node:
            if isinstance(v, list) and (max_depth is None or depth < max_depth):
                yield from _walk(v, depth + 1)
            else:
                yield v
    return list(_walk(values, 0))

if __name__ == '__main__':
    data = [1, [2, 3, [4, 5]], 6, [7, [8, [9]]]]
    print(flatten_recursive(data))
    print(flatten_iterative(data))
    print(flatten_any_depth(data, max_depth=1))
```

Notes: recursive is simplest; iterative avoids stack overflow; `max_depth` allows partial flattening.

Order-preserving deduplication:

```python
def dedupe(values):
    seen = set()
    result = []
    for v in values:
        if v not in seen:
            seen.add(v)
            result.append(v)
    return result

def dedupe_hashable(values):
    return list(dict.fromkeys(values))

def dedupe_by_key(values, key_fn):
    seen = set()
    result = []
    for v in values:
        k = key_fn(v)
        if k not in seen:
            seen.add(k)
            result.append(v)
    return result

if __name__ == '__main__':
    data = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5]
    print(dedupe(data))
    print(dedupe_hashable(data))

    people = [{'id': 1, 'name': 'Alice'}, {'id': 2, 'name': 'Bob'}, {'id': 1, 'name': 'Alice2'}]
    print(dedupe_by_key(people, lambda p: p['id']))
```

