  return function curried(...args) {
    if (args.length >= fn.length) {
      return fn.apply(this, args);
    }
    return function (...more) {
      return curried.apply(this, args.concat(more));
    };
  };
}

function add3(a, b, c) {
  return a + b + c;
}

const curried = curry(add3);
console.log(curried(1)(2)(3));       // 6
console.log(curried(1, 2)(3));       // 6
console.log(curried(1)(2, 3));       // 6
console.log(curried(1, 2, 3));       // 6

// Real-world: partial application
function log(level, message, timestamp) {
  return `[${timestamp}] ${level}: ${message}`;
}
const withTime = curry(log);
const errorLog = withTime('ERROR');
console.log(errorLog('Something broke')('2024-01-01'));
```

Notes: uses `fn.length` to know how many arguments are needed. Curry is useful for building reusable partial functions.

A minimal observable state store:

```javascript
function createStore(initialState) {
  let state = initialState;
  const listeners = new Set();

  return {
    getState: () => state,

    setState(updater) {
      const next = typeof updater === 'function' ? updater(state) : updater;
      if (next === state) return;
      state = { ...state, ...next };
      for (const listener of listeners) listener(state);
    },

    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

const store = createStore({ count: 0, name: 'Alice' });

const unsubscribe = store.subscribe(s => console.log('changed:', s));
store.setState({ count: 1 });
store.setState(prev => ({ count: prev.count + 1 }));
unsubscribe();
store.setState({ name: 'Bob' });

console.log('final:', store.getState());
```

Notes: `setState` accepts an object or a function of the previous state. The subscribe function returns an unsubscribe.

