Creating and composing promises:

```javascript
// Create a promise
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function fetchValue(shouldFail) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (shouldFail) reject(new Error('failed'));
      else resolve('ok');
    }, 100);
  });
}

// Compose
async function run() {
  await delay(200);
  console.log('after 200ms');

  // Sequential
  const a = await fetchValue(false);
  console.log('a:', a);

  // Parallel
  const [b, c] = await Promise.all([
    fetchValue(false),
    fetchValue(false),
  ]);
  console.log('b, c:', b, c);

  // Race — fastest wins
  const first = await Promise.race([
    delay(100).then(() => 'slow'),
    delay(50).then(() => 'fast'),
  ]);
  console.log('winner:', first);

  // allSettled — never rejects
  const results = await Promise.allSettled([
    fetchValue(false),
    fetchValue(true),
  ]);
  console.log(results);

  // Error handling
  try {
    await fetchValue(true);
  } catch (err) {
    console.log('caught:', err.message);
  }
}

run();
```

Notes: `Promise.all` rejects on first error; `Promise.allSettled` never rejects; `Promise.any` resolves with first success; `Promise.race` resolves with first settled.

A single-layer perceptron from scratch (no libraries):

```python
import random

def sigmoid(x):
    return 1 / (1 + math.exp(-x))

import math

def train_perceptron(X, y, epochs=100, lr=0.1):
    n_features = len(X[0])
    weights = [random.uniform(-0.1, 0.1) for _ in range(n_features)]
    bias = 0.0

    for epoch in range(epochs):
        total_error = 0.0
        for xi, yi in zip(X, y):
            z = sum(w * x for w, x in zip(weights, xi)) + bias
            pred = sigmoid(z)
            error = yi - pred
            total_error += error ** 2
            for j in range(n_features):
                weights[j] += lr * error * xi[j]
            bias += lr * error
        if epoch % 10 == 0:
            print(f'epoch {epoch}: loss={total_error:.4f}')
    return weights, bias

def predict(xi, weights, bias):
    z = sum(w * x for w, x in zip(weights, xi)) + bias
    return sigmoid(z)

if __name__ == '__main__':
    X = [[0, 0], [0, 1], [1, 0], [1, 1]]
    y = [0, 1, 1, 0]  # XOR — this simple net cannot learn it, only illustrative
    weights, bias = train_perceptron(X, y)
    for xi in X:
        print(xi, '->', predict(xi, weights, bias))
```

Notes: this is a single-layer perceptron. It cannot solve XOR — you need a hidden layer. For real work use PyTorch or TensorFlow.

