Watching a folder for changes with `watchdog`:

```python
import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class Handler(FileSystemEventHandler):
    def on_created(self, event):
        if not event.is_directory:
            print(f'CREATED: {event.src_path}')

    def on_modified(self, event):
        if not event.is_directory:
            print(f'MODIFIED: {event.src_path}')

    def on_deleted(self, event):
        if not event.is_directory:
            print(f'DELETED: {event.src_path}')

    def on_moved(self, event):
        if not event.is_directory:
            print(f'MOVED: {event.src_path} -> {event.dest_path}')

def watch(path):
    observer = Observer()
    observer.schedule(Handler(), path, recursive=True)
    observer.start()
    print(f'Watching {path}... (Ctrl+C to stop)')
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == '__main__':
    watch('.')
```

Install with `pip install watchdog`. Notes: `recursive=True` watches subfolders too. Runs on Linux, macOS, and Windows.

Retry helper with exponential backoff:

```python
import time
import random
from functools import wraps

def retry(max_attempts=5, base_delay=0.5, max_delay=30.0, exceptions=(Exception,)):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    if attempt == max_attempts:
                        raise
                    delay = min(max_delay, base_delay * 2 ** (attempt - 1))
                    jitter = random.uniform(0, delay * 0.1)
                    print(f'{func.__name__} failed ({e}), retrying in {delay + jitter:.2f}s')
                    time.sleep(delay + jitter)
        return wrapper
    return decorator

@retry(max_attempts=4, exceptions=(ValueError,))
def flaky():
    import random
    if random.random() < 0.7:
        raise ValueError('not this time')
    return 'success'

if __name__ == '__main__':
    print(flaky())
```

Notes: exponential backoff with jitter prevents thundering herd. Only retry on transient errors, not logic errors.

Reading `sys.argv` directly, plus a clean pattern:

```python
import sys

def parse_args(argv):
    options = {'verbose': False, 'output': None, 'files': []}
    i = 1  # skip script name
    while i < len(argv):
        arg = argv[i]
        if arg in ('-v', '--verbose'):
            options['verbose'] = True
        elif arg in ('-o', '--output'):
            i += 1
            if i >= len(argv):
                raise ValueError('--output needs a value')
            options['output'] = argv[i]
        elif arg.startswith('--'):
            raise ValueError(f'Unknown option: {arg}')
        elif arg.startswith('-'):
            raise ValueError(f'Unknown flag: {arg}')
        else:
            options['files'].append(arg)
        i += 1
    return options

if __name__ == '__main__':
    try:
        opts = parse_args(sys.argv)
        print(opts)
    except ValueError as e:
        print(f'Error: {e}', file=sys.stderr)
        sys.exit(1)
```

Notes: for anything nontrivial, use `argparse`. This is only for simple scripts where you want zero dependencies.

