A hash-based SPA router:

```javascript
class Router {
  constructor() {
    this.routes = new Map();
    this.fallback = () => console.log('404');
    window.addEventListener('hashchange', () => this.resolve());
    window.addEventListener('load', () => this.resolve());
  }

  on(pattern, handler) {
    this.routes.set(pattern, handler);
    return this;
  }

  otherwise(handler) {
    this.fallback = handler;
    return this;
  }

  resolve() {
    const path = window.location.hash.slice(1) || '/';
    for (const [pattern, handler] of this.routes) {
      const params = this.match(pattern, path);
      if (params) return handler(params);
    }
    this.fallback(path);
  }

  match(pattern, path) {
    const pParts = pattern.split('/').filter(Boolean);
    const tParts = path.split('/').filter(Boolean);
    if (pParts.length !== tParts.length) return null;
    const params = {};
    for (let i = 0; i < pParts.length; i++) {
      if (pParts[i].startsWith(':')) {
        params[pParts[i].slice(1)] = decodeURIComponent(tParts[i]);
      } else if (pParts[i] !== tParts[i]) {
        return null;
      }
    }
    return params;
  }

  navigate(path) {
    window.location.hash = path;
  }
}

const router = new Router();
router
  .on('/', () => console.log('home'))
  .on('/users/:id', ({ id }) => console.log('user', id))
  .otherwise(path => console.log('not found:', path));

// router.navigate('/users/42');
```

Notes: hash routing works without server configuration. For history-based routing, use the History API and configure your server to fall back to index.html.

