A singly linked list with common operations:

```javascript
class ListNode {
  constructor(value) {
    this.value = value;
    this.next = null;
  }
}

class LinkedList {
  constructor() {
    this.head = null;
    this.size = 0;
  }

  append(value) {
    const node = new ListNode(value);
    if (!this.head) {
      this.head = node;
    } else {
      let cur = this.head;
      while (cur.next) cur = cur.next;
      cur.next = node;
    }
    this.size++;
    return this;
  }

  prepend(value) {
    const node = new ListNode(value);
    node.next = this.head;
    this.head = node;
    this.size++;
    return this;
  }

  remove(value) {
    if (!this.head) return false;
    if (this.head.value === value) {
      this.head = this.head.next;
      this.size--;
      return true;
    }
    let cur = this.head;
    while (cur.next && cur.next.value !== value) cur = cur.next;
    if (cur.next) {
      cur.next = cur.next.next;
      this.size--;
      return true;
    }
    return false;
  }

  toArray() {
    const out = [];
    for (let cur = this.head; cur; cur = cur.next) out.push(cur.value);
    return out;
  }

  reverse() {
    let prev = null, cur = this.head;
    while (cur) {
      const next = cur.next;
      cur.next = prev;
      prev = cur;
      cur = next;
    }
    this.head = prev;
    return this;
  }
}

const list = new LinkedList();
list.append(1).append(2).append(3);
console.log(list.toArray());
list.reverse();
console.log(list.toArray());
```

Notes: reverse is a classic interview problem. Remember to save `next` before reassigning `cur.next`.

A BST with insert, search, and inorder traversal:

```javascript
class TreeNode {
  constructor(value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class BST {
  constructor() {
    this.root = null;
  }

  insert(value) {
    const node = new TreeNode(value);
    if (!this.root) { this.root = node; return this; }
    let cur = this.root;
    while (true) {
      if (value < cur.value) {
        if (!cur.left) { cur.left = node; return this; }
        cur = cur.left;
      } else if (value > cur.value) {
        if (!cur.right) { cur.right = node; return this; }
        cur = cur.right;
      } else {
        return this;  // duplicate, ignore
      }
    }
  }

  has(value) {
    let cur = this.root;
    while (cur) {
      if (value === cur.value) return true;
      cur = value < cur.value ? cur.left : cur.right;
    }
    return false;
  }

  inorder(node = this.root, out = []) {
    if (!node) return out;
    this.inorder(node.left, out);
    out.push(node.value);
    this.inorder(node.right, out);
    return out;
  }

  height(node = this.root) {
    if (!node) return 0;
    return 1 + Math.max(this.height(node.left), this.height(node.right));
  }
}

const tree = new BST();
[5, 3, 8, 1, 4, 7, 9].forEach(v => tree.insert(v));
console.log('inorder:', tree.inorder());
console.log('has 4:', tree.has(4));
console.log('height:', tree.height());
```

Notes: sorted insertion gives O(n) height (worst case). Self-balancing variants (AVL, Red-Black) fix this.

Debounce variants including leading and trailing edge:

```javascript
function debounce(fn, delay, { leading = false, trailing = true } = {}) {
  let timer = null;
  let lastArgs = null;

  function invoke() {
    if (trailing && lastArgs) {
      fn.apply(this, lastArgs);
      lastArgs = null;
    }
    timer = null;
  }

  return function (...args) {
    lastArgs = args;
    const callNow = leading && !timer;

    if (timer) clearTimeout(timer);
    timer = setTimeout(invoke.bind(this), delay);

    if (callNow) {
      fn.apply(this, args);
      lastArgs = null;
    }
  };
}

// Leading only (fires at the start)
const onDragStart = debounce(console.log, 300, { leading: true, trailing: false });

// Trailing only (fires at the end)
const onSearch = debounce(console.log, 300, { leading: false, trailing: true });

onSearch('a');
onSearch('ab');
onSearch('abc');
```

Notes: leading fires on the first call; trailing fires after silence. Combining both fires at start and end.

A multi-client chat server using `selectors`:

```python
import selectors
import socket
import sys

sel = selectors.DefaultSelector()
clients = {}

def accept(sock):
    conn, addr = sock.accept()
    conn.setblocking(False)
    print(f'Connected: {addr}')
    clients[conn] = addr
    sel.register(conn, selectors.EVENT_READ, data=handle_client)

def handle_client(conn):
    try:
        data = conn.recv(1024)
    except ConnectionResetError:
        data = b''

    if data:
        print(f'{clients[conn]}: {data.decode().strip()}')
        broadcast(conn, data)
    else:
        print(f'Disconnected: {clients[conn]}')
        sel.unregister(conn)
        conn.close()
        del clients[conn]

def broadcast(sender, data):
    for conn in list(clients):
        if conn is sender:
            continue
        try:
            conn.sendall(data)
        except Exception:
            sel.unregister(conn)
            conn.close()
            clients.pop(conn, None)

if __name__ == '__main__':
    host, port = '0.0.0.0', 9999
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((host, port))
    server.listen()
    server.setblocking(False)
    sel.register(server, selectors.EVENT_READ, data=accept)
    print(f'Listening on {host}:{port}')

    try:
        while True:
            events = sel.select(timeout=1)
            for key, _ in events:
                key.data(key.fileobj)
    except KeyboardInterrupt:
        print('shutting down')
    finally:
        for conn in list(clients):
            conn.close()
        server.close()
        sel.close()
```

Notes: `selectors` handles many clients on one thread. Test with `nc localhost 9999` from multiple terminals.

A simple todo list with file persistence:

```python
import json
import sys
from pathlib import Path

DATA_FILE = Path.home() / '.todos.json'

def load():
    if not DATA_FILE.exists():
        return []
    try:
        return json.loads(DATA_FILE.read_text())
    except json.JSONDecodeError:
        return []

def save(items):
    DATA_FILE.write_text(json.dumps(items, indent=2))

def add(text):
    items = load()
    items.append({'id': len(items) + 1, 'text': text, 'done': False})
    save(items)
    print(f'Added: {text}')

def list_items():
    items = load()
    if not items:
        print('No todos')
        return
    for item in items:
        mark = 'x' if item['done'] else ' '
        print(f'[{mark}] {item["id"]}. {item["text"]}')

def done(item_id):
    items = load()
    for item in items:
        if item['id'] == item_id:
            item['done'] = True
            save(items)
            print('Marked done')
            return
    print('Not found')

def remove(item_id):
    items = [i for i in load() if i['id'] != item_id]
    save(items)
    print('Removed')

def main():
    if len(sys.argv) < 2:
        print('Usage: todo [add|list|done|remove] [args]')
        return
    cmd = sys.argv[1]
    if cmd == 'add' and len(sys.argv) >= 3:
        add(' '.join(sys.argv[2:]))
    elif cmd == 'list':
        list_items()
    elif cmd == 'done' and len(sys.argv) >= 3:
        done(int(sys.argv[2]))
    elif cmd == 'remove' and len(sys.argv) >= 3:
        remove(int(sys.argv[2]))
    else:
        print('Unknown command')

if __name__ == '__main__':
    main()
```

Usage: `python todo.py add "Buy milk"`, `python todo.py list`, `python todo.py done 1`. Notes: stores in the home directory so it works from any folder.

