LRU cache with a doubly linked list and dictionary:

```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError('capacity must be at least 1')
        self.capacity = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return None
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)
        self.data[key] = value
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)

    def __len__(self):
        return len(self.data)

    def __repr__(self):
        return f'LRUCache({dict(self.data)})'

if __name__ == '__main__':
    cache = LRUCache(2)
    cache.put('a', 1)
    cache.put('b', 2)
    print(cache.get('a'))  # 1
    cache.put('c', 3)
    print(cache.get('b'))  # None (evicted)
    print(cache.get('c'))  # 3
```

Notes: `OrderedDict.move_to_end` gives O(1) reordering. Python's `functools.lru_cache` is faster for function memoization.

Sequential execution queue for async tasks:

```javascript
class TaskQueue {
  constructor(concurrency = 1) {
    this.concurrency = concurrency;
    this.running = 0;
    this.queue = [];
  }

  add(task) {
    return new Promise((resolve, reject) => {
      this.queue.push({ task, resolve, reject });
      this.next();
    });
  }

  next() {
    if (this.running >= this.concurrency || this.queue.length === 0) return;
    const { task, resolve, reject } = this.queue.shift();
    this.running++;
    Promise.resolve()
      .then(task)
      .then(resolve, reject)
      .finally(() => {
        this.running--;
        this.next();
      });
  }

  size() {
    return this.queue.length + this.running;
  }
}

const q = new TaskQueue(2);
for (let i = 1; i <= 5; i++) {
  q.add(async () => {
    await new Promise(r => setTimeout(r, 200));
    console.log('task', i);
    return i;
  }).then(v => console.log('done', v));
}
```

Notes: useful for rate-limiting HTTP requests. Increase `concurrency` to run more tasks in parallel.

Parsing CSV text with proper quote handling:

```javascript
function parseCSV(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"' && text[i + 1] === '"') {
        field += '"';
        i++;
      } else if (ch === '"') {
        inQuotes = false;
      } else {
        field += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ',') {
        row.push(field);
        field = '';
      } else if (ch === '\n') {
        row.push(field);
        rows.push(row);
        row = [];
        field = '';
      } else if (ch === '\r') {
        // ignore
      } else {
        field += ch;
      }
    }
  }

  if (field || row.length) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

const csv = `name,age,note
Alice,30,"Hello, world"
Bob,25,Simple
`;
console.log(parseCSV(csv));
```

Notes: handles quoted fields, escaped quotes (`""`), and both `\n` and `\r\n` line endings.

Several string similarity algorithms:

```python
import difflib
from collections import Counter

def similarity_ratio(a, b):
    return difflib.SequenceMatcher(None, a, b).ratio()

def jaccard_word_similarity(a, b):
    a_words = set(a.lower().split())
    b_words = set(b.lower().split())
    if not a_words and not b_words:
        return 1.0
    return len(a_words & b_words) / len(a_words | b_words)

def cosine_char_similarity(a, b):
    a_chars = Counter(a)
    b_chars = Counter(b)
    common = set(a_chars) & set(b_chars)
    dot = sum(a_chars[c] * b_chars[c] for c in common)
    norm_a = sum(v * v for v in a_chars.values()) ** 0.5
    norm_b = sum(v * v for v in b_chars.values()) ** 0.5
    return dot / (norm_a * norm_b) if norm_a and norm_b else 0

def fuzzy_contains(needle, haystack, threshold=0.75):
    needle = needle.lower()
    haystack = haystack.lower()
    if needle in haystack:
        return True
    words = haystack.split()
    for i, word in enumerate(words):
        for length in range(len(needle.split()) + 1):
            chunk = ' '.join(words[i:i+length+1])
            if chunk and difflib.SequenceMatcher(None, needle, chunk).ratio() >= threshold:
                return True
    return False

if __name__ == '__main__':
    pairs = [('python', 'pyton'), ('hello world', 'hello word'), ('python', 'java')]
    for a, b in pairs:
        print(f'{a!r} vs {b!r}: {similarity_ratio(a, b):.3f}')
```

Notes: `SequenceMatcher` uses Ratcliff-Obershelp. For production, use RapidFuzz or thefuzz (formerly fuzzywuzzy).

Set operations on arrays:

```javascript
function union(...arrays) {
  return [...new Set(arrays.flat())];
}

function intersection(a, b) {
  const setB = new Set(b);
  return [...new Set(a.filter(x => setB.has(x)))];
}

function difference(a, b) {
  const setB = new Set(b);
  return [...new Set(a.filter(x => !setB.has(x)))];
}

function symmetricDifference(a, b) {
  return [...new Set([...difference(a, b), ...difference(b, a)])];
}

function isSubset(a, b) {
  const setB = new Set(b);
  return a.every(x => setB.has(x));
}

const a = [1, 2, 3, 4];
const b = [3, 4, 5, 6];

console.log('union:', union(a, b));                    // [1,2,3,4,5,6]
console.log('intersection:', intersection(a, b));       // [3,4]
console.log('difference:', difference(a, b));           // [1,2]
console.log('symmetric:', symmetricDifference(a, b));   // [1,2,5,6]
console.log('subset:', isSubset([1, 2], a));            // true
```

Notes: use a `Set` for O(1) lookups. These functions return new arrays without duplicates.

Converting between JSON, CSV, YAML, and dictionaries:

```python
import json
import csv
import io
from pathlib import Path

def json_to_csv(json_path, csv_path, fieldnames=None):
    data = json.loads(Path(json_path).read_text())
    if not data:
        return
    if fieldnames is None:
        fieldnames = list(data[0].keys())
    with open(csv_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(data)

def csv_to_json(csv_path, json_path):
    with open(csv_path, 'r', encoding='utf-8', newline='') as f:
        rows = list(csv.DictReader(f))
    Path(json_path).write_text(json.dumps(rows, indent=2, ensure_ascii=False))

def csv_string_to_json(csv_string):
    reader = csv.DictReader(io.StringIO(csv_string))
    return json.dumps(list(reader), indent=2)

def json_to_dict_list(json_string):
    return json.loads(json_string)

if __name__ == '__main__':
    sample_csv = 'name,age\nAlice,30\nBob,25\n'
    print(csv_string_to_json(sample_csv))
```

Notes: `newline=''` is required when writing CSV to avoid blank lines on Windows. Use `ensure_ascii=False` to keep non-ASCII characters readable.
